import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.CWSmAuPU.js";const p=JSON.parse('{"title":"0028 外部系统对接：命令写法在配置里，内容由 AI 整理，调用是确定的","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0028-external-integrations.md","filePath":"reference/adr/0028-external-integrations.md","lastUpdated":null}'),i={name:"reference/adr/0028-external-integrations.md"};function n(d,e,l,s,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<div><h1 id="_0028-外部系统对接-命令写法在配置里-内容由-ai-整理-调用是确定的" tabindex="-1">0028 外部系统对接：命令写法在配置里，内容由 AI 整理，调用是确定的 <a class="header-anchor" href="#_0028-外部系统对接-命令写法在配置里-内容由-ai-整理-调用是确定的" aria-label="Permalink to &quot;0028 外部系统对接：命令写法在配置里，内容由 AI 整理，调用是确定的&quot;">​</a></h1><ul><li>状态：已采纳（与 <a href="./0014-notifier-slot">0014</a> 的通知槽并存：通知只发消息，集成会回写）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>团队希望需求同时出现在自己的需求管理系统中：需求开始时建卡，阶段变化时改卡片状态，卡片编号能在需求、报告和插件里看到。对接的系统各不相同，通常提供本机命令行工具（例如需求管理系统的 CLI），参数会随系统升级变化。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><strong>命令写法写在本机或团队配置里，不写进 req-kit 的代码</strong>：<code>integrations</code> 中每项写明工具、建卡和改状态的参数（带占位符）、从输出取卡片编号和链接的正则、各个流水线事件对应的卡片状态。换系统或系统改参数只改配置。项目配置不能写 <code>integrations</code>（它会运行命令），只能用 <code>integrationDefaults</code> 提供自己的取值，例如项目编号。</li><li><strong>AI 整理内容，不决定怎么调用</strong>：卡片的业务字段（<code>cardFields</code>，如优先级、需求类型、子系统）由 <code>/req</code> 在需求说明确认时从需求说明中整理，和需求方一起确认后写进 <code>card.json</code>。运行时引擎按配置把这些值填进参数并执行，每次行为一致、可以补发、不会重复建卡；不在每次调用时让 AI 读帮助、拼命令，避免结果不确定、在真实系统上做错操作和难以复现。配置本身可以请 AI 读工具的帮助起草，由人确认。</li><li><strong>不经过 shell</strong>：参数数组直接传给进程，标题和 Markdown 描述中的空格、换行、引号都原样传递。Windows 上 npm 安装的工具是 <code>.cmd</code> 包装，只有 cmd.exe 能运行，而 cmd.exe 会破坏这类参数，所以改用 node 直接运行包装里指向的脚本。</li><li><strong>外部系统出错不影响流水线</strong>：失败或超时的调用记在状态文件的 <code>external.&lt;名称&gt;.pending</code>，下一个事件时先按顺序补发；卡片没建好时状态排在后面；等待中的状态只留最新的一个。流水线没在运行时可以 <code>req sync</code>。</li><li><strong>先试再用</strong>：<code>req integration test</code> 打印每个事件会执行的完整命令而不调用。</li><li>录入测试用例暂不做，等对接系统提供能力后，作为新的动作和事件加入（例如功能验证结束时把验收标准和结果录入）。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>新的状态文件字段 <code>external</code>（可选，格式版本仍为 1）、功能目录文件 <code>card.json</code>、<code>req api status</code> 的 <code>external</code>。</li><li><code>/req</code> 在确认需求说明前运行&quot;卡片字段&quot;命令；没有配置对接时它输出&quot;跳过&quot;。</li><li>事件：started、approval、blocked、phase_done、verify、completed（可按结论细分）、failed。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0028-external-integrations.md">docs/adr/0028-external-integrations.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0028-external-integrations.md">在 GitHub 上编辑</a></p>',2)])])}const g=a(i,[["render",n]]);export{p as __pageData,g as default};
